+func TestDisabledReporterDoesNotCreateState(t *testing.T) {
+	dir := filepath.Join(t.TempDir(), "state")
+	cfg := config.Default()
+	cfg.Meta.TelemetryEnabled = false
+	cfg.Meta.StateDirectory = dir
+	reporter, err := NewReporter(cfg, logrus.New())
+	if err != nil || reporter != nil {
+		t.Fatalf("reporter=%v, err=%v", reporter, err)
+	}
+	if _, err := os.Stat(dir); !os.IsNotExist(err) {
+		t.Fatalf("state directory created: %v", err)
+	}
+}
+
+func TestReporterPersistsStableUUIDAndReportsAnonymousEvent(t *testing.T) {
+	dir := t.TempDir()
+	var event map[string]interface{}
+	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		if err := json.NewDecoder(r.Body).Decode(&event); err != nil {
+			t.Errorf("decode event: %v", err)
+		}
+		w.WriteHeader(http.StatusOK)
+	}))
+	defer server.Close()
+	old := endpoint
+	endpoint = server.URL
+	defer func() { endpoint = old }()
+	cfg := config.Default()
+	cfg.Meta.StateDirectory = dir
+	reporter, err := NewReporter(cfg, logrus.New())
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := reporter.Report(context.Background()); err != nil {
+		t.Fatal(err)
+	}
+	raw, err := os.ReadFile(filepath.Join(dir, "telemetry.json"))
+	if err != nil {
+		t.Fatal(err)
+	}
+	var state struct {
+		Version       string `json:"version"`
+		UUID          string `json:"uuid"`
+		LastTimestamp string `json:"lastTimestamp"`
+	}
+	if err := json.Unmarshal(raw, &state); err != nil {
+		t.Fatal(err)
+	}
+	if state.UUID == "" {
+		t.Fatal("missing uuid")
+	}
+	if _, err := time.Parse(time.RFC3339, state.LastTimestamp); err != nil {
+		t.Fatal(err)
+	}
+	if event["event"] != "flipt.ping" || event["anonymousId"] != state.UUID {
+		t.Fatalf("unexpected event: %v", event)
+	}
+	props, ok := event["properties"].(map[string]interface{})
+	if !ok || props["uuid"] != state.UUID || props["version"] != state.Version {
+		t.Fatalf("unexpected properties: %v", event["properties"])
+	}
+	flipt, ok := props["flipt"].(map[string]interface{})
+	if !ok || flipt["version"] != "dev" {
+		t.Fatalf("unexpected flipt metadata: %v", props["flipt"])
+	}
+	reporter2, err := NewReporter(cfg, logrus.New())
+	if err != nil {
+		t.Fatal(err)
+	}
+	if reporter2.state.UUID != state.UUID {
+		t.Fatal("uuid changed across restarts")
+	}
+}
